texts=[];ids={}
for k in ['source-original-en','modern-en','modern-da']:
 for c in json.loads((p/(k+'.json')).read_text())['chapters']:
  for i,s in enumerate(c['paragraphs'],1):
   s=re.sub(r'^[^a-zæøå.]{1,28}\. ','',s).strip('[]'); tok=t.encode(s,add_special_tokens=False).ids
   indices=[]
   for pos in range(0,len(tok),112):
    indices.append(len(texts));texts.append([cls]+tok[pos:pos+112]+[eos])
   ids[(k,c['number'],i)]=indices
vectors={}
for a in range(0,len(texts),20):
 if not a%400:print(a,len(texts),flush=True)
 subset=sorted(range(len(texts)),key=lambda i:len(texts[i]))[a:a+20]; length=max(len(texts[i]) for i in subset)
 X=np.array([texts[i]+[pad]*(length-len(texts[i])) for i in subset],dtype=np.int64); mask=(X!=pad).astype(np.int64)
 inp={'input_ids':X,'attention_mask':mask,'token_type_ids':np.zeros_like(X)}
 H=m.run(None,{i.name:inp[i.name] for i in m.get_inputs()})[0];V=(H*mask[:,:,None]).sum(1)/mask.sum(1)[:,None]
 for i,v in zip(subset,V):vectors[i]=v
def seq(k,c,i):
 a=ids[(k,c,i)];v=np.average([vectors[n] for n in a],axis=0,weights=[len(texts[n])-2 for n in a]); return v/np.linalg.norm(v)
rows=[]
for k,c,i in ids:
 if k!='modern-da':continue
 o,e,d=[seq(n,c,i) for n in ['source-original-en','modern-en','modern-da']]
